<?php require_once __DIR__.'/includes/auth.php';$id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT e.*,(SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id AND r.status='valid') registered_count FROM events e WHERE e.id=?");$st->execute([$id]);$ev=$st->fetch();if(!$ev){http_response_code(404);$pageTitle='Event not found';require __DIR__.'/includes/header.php';echo '<div class="container section"><h1>Event not found</h1><a href="events.php">Back to events</a></div>';require __DIR__.'/includes/footer.php';exit;}$pageTitle=$ev['title'];$open=event_open($ev);require __DIR__.'/includes/header.php'; ?>
<section class="section section-soft"><div class="container"><a href="events.php" class="text-decoration-none"><i class="bi bi-arrow-left"></i> All events</a><div class="row g-5 mt-2"><div class="col-lg-7"><img class="w-100 rounded-4 shadow-sm" style="max-height:450px;object-fit:cover" src="<?=e(event_image($ev['image_url']))?>" alt="<?=e($ev['title'])?>" onerror="this.src='https://placehold.co/1000x600/eef2ff/315eea?text=CampusPass'"><div class="panel mt-4"><span class="category-pill"><?=e($ev['category'])?></span><h1 class="mt-3"><?=e($ev['title'])?></h1><p class="muted" style="white-space:pre-line"><?=e($ev['description'])?></p><h2 class="h5 mt-4">Event rules & instructions</h2><p class="muted" style="white-space:pre-line"><?=e($ev['rules']?:'Bring your digital ticket and arrive a little before the event starts. Follow venue staff instructions.')?></p></div></div><div class="col-lg-5"><div class="panel sticky-lg-top" style="top:100px"><span class="status-pill status-<?=e($ev['status'])?>"><?=e($ev['status'])?></span><h2 class="h4 mt-3">Event information</h2><p class="mb-3"><i class="bi bi-calendar3 text-primary me-2"></i><strong><?=e(date('l, M j, Y',strtotime($ev['event_date'])))?></strong><br><span class="muted ms-4"><?=e(date('g:i A',strtotime($ev['start_time'])))?><?= $ev['end_time']?' – '.e(date('g:i A',strtotime($ev['end_time']))):'' ?></span></p><p><i class="bi bi-geo-alt text-primary me-2"></i><?=e($ev['venue'])?></p><p><i class="bi bi-person-badge text-primary me-2"></i>Organiser: <?=e($ev['organiser']?:'CampusPass team')?></p><hr><div class="d-flex justify-content-between mb-2"><span class="muted">Registered</span><strong><?=number_format((int)$ev['registered_count'])?> / <?=number_format((int)$ev['capacity'])?></strong></div><div class="progress mb-3" style="height:8px"><div class="progress-bar" style="width:<?=min(100,round($ev['registered_count']/max(1,$ev['capacity'])*100))?>%"></div></div><?php if($ev['registration_end']): ?><p class="small muted">Registration deadline: <?=e(date('M j, Y g:i A',strtotime($ev['registration_end'])))?></p><?php endif; ?><?php if($open): ?><a href="registration.php?event_id=<?=(int)$ev['id']?>" class="btn btn-primary btn-lg w-100">Register now <i class="bi bi-arrow-right ms-1"></i></a><?php else: ?><button class="btn btn-secondary btn-lg w-100" disabled>Registration unavailable</button><p class="small muted mt-2 mb-0">This event may be full, closed, unpublished, or outside its registration window.</p><?php endif; ?></div></div></div></div></section><?php require __DIR__.'/includes/footer.php'; ?>
